const d = $input.first().json;
const name = d.patient_name ? d.patient_name : 'there';
let text = '';
if (d.kind === 'booked') {
  text = 'Hello ' + name + ', your appointment is confirmed.\n\nDepartment: ' + d.department + '\nDoctor: ' + d.doctor_name + '\nDate: ' + d.date + '\nTime: ' + d.time + '\nBooking ID: ' + d.appointment_id + '\n\nPlease arrive 10 minutes early.';
} else if (d.kind === 'welcome') {
  text = 'Welcome to City Hospital Front Desk. I can book a doctor appointment for you. Please tell me your name, your problem area (for example skin rash or knee pain), and the date and time you prefer. I cannot give medical advice.';
} else if (d.kind === 'already_booked') {
  text = 'You already have this appointment (Booking ID: ' + d.appointment_id + ') with ' + d.doctor_name + '. No new booking was made.';
} else if (d.kind === 'time_taken') {
  text = 'Sorry, that time is already taken. These times are free:\n' + d.alternatives + '\n\nReply with the time you want.';
} else if (d.kind === 'needs_info') {
  text = 'To book your appointment I still need your ' + d.missing + '. Please send it in your next message.';
} else if (d.kind === 'emergency') {
  text = 'This sounds like an emergency. Please call your local emergency number or go to the nearest emergency room right now. This bot cannot handle emergencies.';
} else if (d.kind === 'refuse') {
  text = 'Sorry, I can only help with booking doctor appointments. Please tell me which doctor or problem area you need.';
} else if (d.kind === 'unclear') {
  text = 'I could not tell which department you need. Please tell me a little more, for example "skin rash" or "knee pain". I only book appointments and cannot give medical advice.';
} else if (d.kind === 'no_slots_that_day' || d.kind === 'fully_booked' || d.kind === 'no_doctor') {
  text = 'Sorry, there are no free appointments for that day. The doctor may not work on that day. Please try another date.';
} else if (d.kind === 'past_date') {
  text = 'That date has already passed. Please send a date from today onwards.';
} else {
  text = 'Sorry, something went wrong on our side. A receptionist will contact you soon.';
}
return [{ json: { chat_id: d.chat_id, text: text, kind: d.kind } }];
